# Write isolated rules and explicit size steps for every element.
for folder in sorted(E.iterdir()):
 e=folder.name;sel=f'[data-el="meridian-deck-{e}"]'
 base='@{box-sizing:border-box;position:relative;min-width:0;min-height:0;container-type:size;anchor-scope:all;font-family:var(--font-body);font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink)}@ *{box-sizing:border-box}@ :is(p,h2,blockquote){margin:0}@ .kick{font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);color:var(--n-7)}@ .name{font-size:var(--type-24);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track)}@ .fig{font-size:var(--type-48);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}@ .note{font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7)}@ .icon{display:inline-block;width:48px;height:48px;flex:none}'
 s=(base+CSS[e]).replace('@',sel)
 responsive=f'\n@container (max-width:520px){{{sel} .name{{font-size:var(--type-18)}}{sel} .note{{font-size:var(--type-14)}}{sel} .fig{{font-size:var(--type-36)}}{sel} .kick{{font-size:var(--type-12)}}}}\n@container (max-width:300px){{{sel} .name{{font-size:var(--type-16)}}{sel} .note{{font-size:var(--type-12)}}{sel} .fig{{font-size:var(--type-28)}}{sel} .mark{{width:56px;height:56px}}{sel} h2{{font-size:var(--type-28)}}}}\n@container (max-height:170px){{{sel} .kick{{display:none}}{sel} .name{{font-size:var(--type-16)}}{sel} .note{{font-size:var(--type-12)}}{sel} .fig{{font-size:var(--type-28)}}}}\n@container (max-height:100px){{{sel} .note{{display:none}}}}\n'
 if e=='chart-line':
  for i in range(1,25):
   s+=f'{sel} .pt:nth-child({i})>b{{anchor-name:--meridian-line-{i}}}'
   if i>1:
    for pseudo,first,last,gradient in [('before',i-1,i,'to top right'),('after',i,i-1,'to bottom right')]:
     s+=f'{sel} .pt:nth-child({i})::{pseudo}'+'{content:"";position:absolute;pointer-events:none;'+f'left:anchor(--meridian-line-{i-1} center);right:anchor(--meridian-line-{i} center);top:calc(anchor(--meridian-line-{first} bottom) - 1px);bottom:calc(anchor(--meridian-line-{last} bottom) - 1px);background:linear-gradient({gradient},transparent calc(50% - 1px),var(--a1) calc(50% - 1px),var(--a1) calc(50% + 1px),transparent calc(50% + 1px));'+'}'
  responsive+=f'@container (max-width:600px){{{sel}:has(.pt:nth-child(8)) .pt:nth-child(even)>span{{visibility:hidden}}}}'
 if e=='chart-area':
  for i in range(1,25):
   s+=f'{sel} .pt:nth-child({i} of .pt){{anchor-name:--meridian-area-{i}}}'
   if i==1:s+=f'{sel} .pt:nth-child(1 of .pt)::before,{sel} .pt:nth-child(1 of .pt)::after{{content:none}}'
   else:s+=f'{sel} .pt:nth-child({i} of .pt)::before,{sel} .pt:nth-child({i} of .pt)::after'+'{'+f'left:anchor(--meridian-area-{i-1} center);right:anchor(--meridian-area-{i} center);top:calc(anchor(--meridian-area-{i-1} top) - (100cqh - var(--gap) - var(--gap-lg)));'+'}'
  responsive+=f'@container (max-width:600px){{{sel} .axis>span:nth-child(even){{visibility:hidden}}}}'
 if e in ['cycle','hub']:
  member='node' if e=='cycle' else 'spoke'
  for n in range(3,7):
   for i in range(n):
    a=i*2*math.pi/n-math.pi/2;x=50+37*math.cos(a);y=50+33*math.sin(a)
    s+=f'{sel}:has(>.{member}:nth-child({n+1}):last-child)>.{member}:nth-child({i+1} of .{member})'+'{'+f'left:{x:.3f}%;top:{y:.3f}%;translate:-50% -50%;'+'}'
 if e=='radar':
  for n in range(3,9):
   # The number of axes defines the exact polygon; values map to its radii.
   coords=[]
   for i in range(n):
    a=i*2*math.pi/n-math.pi/2
    coords.append(f'calc(50% + var(--v{i+1})/var(--max,100)*{50*math.cos(a):.5f}%) calc(50% + var(--v{i+1})/var(--max,100)*{50*math.sin(a):.5f}%)')
    s+=f'{sel}:has(>.axis:nth-child({n}):last-of-type)>.axis:nth-child({i+1})'+'{'+f'left:{50+46*math.cos(a):.3f}%;top:{50+46*math.sin(a):.3f}%;'+'}'
   s+=f'{sel}[style*="--n:{n}"] .series'+'{clip-path:polygon('+','.join(coords)+')}'
 if e in ['roadmap','mindmap']:
  meta=json.loads((folder/'element.json').read_text());meta['tokenDefaults'][f'--meridian-deck-{e}-reserve']='20%' if e=='roadmap' else '28%';(folder/'element.json').write_text(json.dumps(meta,indent=2))
 if e=='tag': s+=sel+'{container-type:normal;}'
 (folder/'element.css').write_text(s+responsive)
 (folder/'description.md').write_text(f'The {e.replace("-"," ")} uses Meridian Deck’s fine structural rules, circular badges, clear sans-serif hierarchy, and one decisive accent. Quiet neutral surfaces hold supporting information while the selected path or key figure receives the strongest fill. Its spacing and type step down with the available container so labels remain distinct from the plotted or connected geometry.')
print('Own element CSS files:',len(CSS))
